#!/usr/bin/env python3
# Exact reconstruction of artifact 621a26ec7b4419d76351b43e22fff9df644945c6458e2a531d2542a0819b6602
# (lower=[2,2,2,0,0], upper=[5,5,5,5,5], hDegrees=[1,2,3,4,5]).
SOURCE_ARTIFACT='621a26ec7b4419d76351b43e22fff9df644945c6458e2a531d2542a0819b6602'
LOW=(2,2,2,0,0); UP=(5,5,5,5,5)
GL=[(2,2,2,0,0),(2,2,2,1,0),(2,2,2,2,0),(2,2,2,1,1),(2,2,2,2,1),(2,2,2,2,2)]
GR=[(2,2,2,0,0),(3,2,2,0,0),(4,2,2,0,0),(3,3,2,0,0),(4,3,2,0,0),(4,4,2,0,0)]
def wt(x): return sum(x)
def fmtpart(x):
 s=''.join(map(str,[a for a in x if a]))
 return s or '0'
def eye(n): return [[int(i==j) for j in range(n)] for i in range(n)]
def mm(A,B): return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def tr(A): return [list(x) for x in zip(*A)]
def matstr(A): return '['+'; '.join('['+','.join(map(str,r))+']' for r in A)+']'
def det(A):
 A=[r[:] for r in A]; n=len(A); sign=1; prev=1
 if n==0:return 1
 for k in range(n-1):
  p=next((i for i in range(k,n) if A[i][k]),None)
  if p is None:return 0
  if p!=k:A[k],A[p]=A[p],A[k];sign=-sign
  q=A[k][k]
  for i in range(k+1,n):
   for j in range(k+1,n): A[i][j]=(A[i][j]*q-A[i][k]*A[k][j])//prev
  prev=q
  for i in range(k+1,n):A[i][k]=0
 return sign*A[-1][-1]
def parts(d):
 out=[]
 def rec(i,last,rem,a):
  if i==5:
   if rem==0 and all(LOW[j]<=a[j]<=UP[j] for j in range(5)):out.append(tuple(a))
   return
  for x in range(min(last,UP[i],rem),LOW[i]-1,-1):rec(i+1,x,rem-x,a+[x])
 rec(0,5,d,[]); return out
def horiz(lam,mu):
 # mu/lam horizontal iff mu_i >= lam_i >= mu_{i+1}
 return all(mu[i]>=lam[i] and lam[i]>=mu[i+1] for i in range(4)) and mu[4]>=lam[4]
def addrow(A,i,j,q): A[i]=[x+q*y for x,y in zip(A[i],A[j])]
def addcol(A,i,j,q):
 for r in A:r[i]+=q*r[j]
def swaprow(A,i,j):A[i],A[j]=A[j],A[i]
def swapcol(A,i,j):
 for r in A:r[i],r[j]=r[j],r[i]
def smith(M):
 A=[r[:] for r in M]; m=len(A);n=len(A[0]) if m else 0;U=eye(m);V=eye(n);k=0
 while k<m and k<n:
  pos=None
  for i in range(k,m):
   for j in range(k,n):
    if A[i][j] and (pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]])):pos=(i,j)
  if pos is None:break
  swaprow(A,k,pos[0]);swaprow(U,k,pos[0]);swapcol(A,k,pos[1]);swapcol(V,k,pos[1])
  while True:
   changed=True
   while changed:
    changed=False
    for i in range(k+1,m):
     if A[i][k]:
      q=A[i][k]//A[k][k];addrow(A,i,k,-q);addrow(U,i,k,-q)
      if abs(A[i][k])<abs(A[k][k]) and A[i][k]:swaprow(A,i,k);swaprow(U,i,k)
      changed=True;break
    if changed:continue
    for j in range(k+1,n):
     if A[k][j]:
      q=A[k][j]//A[k][k];addcol(A,j,k,-q);addcol(V,j,k,-q)
      if abs(A[k][j])<abs(A[k][k]) and A[k][j]:swapcol(A,j,k);swapcol(V,j,k)
      changed=True;break
   bad=None
   for i in range(k+1,m):
    for j in range(k+1,n):
     if A[i][j]%A[k][k]:bad=(i,j);break
    if bad:break
   if not bad:break
   # inject an offending entry into pivot row, then column Euclidean reduction
   addrow(A,k,bad[0],1);addrow(U,k,bad[0],1)
  if A[k][k]<0:
   A[k]=[-x for x in A[k]];U[k]=[-x for x in U[k]]
  k+=1
 return U,A,V,k
def inv_unimod(A):
 n=len(A); B=[A[i][:]+eye(n)[i] for i in range(n)]
 for k in range(n):
  p=next(i for i in range(k,n) if abs(B[i][k])==1)
  if p!=k:B[k],B[p]=B[p],B[k]
  if B[k][k]==-1:B[k]=[-x for x in B[k]]
  for i in range(n):
   if i!=k and B[i][k]:
    q=B[i][k];B[i]=[x-q*y for x,y in zip(B[i],B[k])]
 return [r[n:] for r in B]
def selection(basis,fam,d):
 x=[z for z in fam if wt(z)==d]
 return [[int(b==z) for z in x] for b in basis],x
def checkeq(A,B):return A==B
print('SOURCE_ARTIFACT='+SOURCE_ARTIFACT)
for d in range(6,11):
 B=parts(d); rows=[]; labels=[]
 for t in range(1,6):
  for lam in parts(d-t):
   rows.append([int(horiz(lam,mu)) for mu in B]);labels.append('h%d*s%s'%(t,fmtpart(lam)))
 M=rows; U,D,V,r=smith(M); n=len(B)
 # all stated relation ranks here have free quotient; C is normalized via G_L selection
 L,gl=selection(B,GL,d); R,gr=selection(B,GR,d)
 C0=U[r:]
 CL0=mm(C0,L)
 C=mm(inv_unimod(CL0),C0)
 T=mm(C,R)
 expected={6:[[1]],7:[[-1]],8:[[0,1],[1,0]],9:[[-1]],10:[[1]]}[d]
 ok=(checkeq(mm(mm(U,M),V),D) and checkeq(mm(C,tr(M)),[[0]*len(M) for _ in range(len(C))]) and checkeq(mm(C,L),eye(len(gl))) and checkeq(T,expected) and abs(det(U))==1 and abs(det(V))==1 and all(D[i][i]==1 for i in range(r)))
 print('DEGREE',d)
 print('B='+str([fmtpart(x) for x in B]))
 print('ROWS='+str(labels))
 print('M='+matstr(M));print('U='+matstr(U));print('V='+matstr(V));print('D='+matstr(D));print('C='+matstr(C));print('L='+matstr(L));print('R='+matstr(R));print('T='+matstr(T))
 print('VERIFY U*M*V=D:',checkeq(mm(mm(U,M),V),D),'C*M^T=0:',checkeq(mm(C,tr(M)),[[0]*len(M) for _ in range(len(C))]),'C*L=I:',checkeq(mm(C,L),eye(len(gl))),'C*R=T:',checkeq(T,expected),'detU=',det(U),'detV=',det(V),'ones=',all(D[i][i]==1 for i in range(r)),'EXPECTED_T=',matstr(expected),'PASS=',ok)
 assert ok
print('ALL_CERTIFICATES_PASS')
